import React, { useState, useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import ProductCard from '../../components/marketplace/ProductCard';
import { PRODUCTS, CATEGORIES } from '../../utils/dummyData';
import './Products.css';

const SORT_OPTIONS = [
  { value: 'featured', label: 'Featured' },
  { value: 'price_asc', label: 'Price: Low to High' },
  { value: 'price_desc', label: 'Price: High to Low' },
  { value: 'rating', label: 'Avg. Customer Review' },
  { value: 'newest', label: 'Newest Arrivals' },
];

const Products = () => {
  const [params, setParams] = useSearchParams();
  const [sort, setSort] = useState('featured');
  const [priceRange, setPriceRange] = useState([0, 200000]);
  const [selectedBrands, setSelectedBrands] = useState([]);
  const [minRating, setMinRating] = useState(0);

  const searchQ = params.get('search') || '';
  const categoryQ = params.get('category') || '';

  const brands = [...new Set(PRODUCTS.map(p => p.brand))];

  const filtered = useMemo(() => {
    let list = [...PRODUCTS];
    if (searchQ) list = list.filter(p => p.name.toLowerCase().includes(searchQ.toLowerCase()) || p.brand.toLowerCase().includes(searchQ.toLowerCase()));
    if (categoryQ) list = list.filter(p => p.category === categoryQ);
    if (selectedBrands.length) list = list.filter(p => selectedBrands.includes(p.brand));
    list = list.filter(p => p.price >= priceRange[0] && p.price <= priceRange[1]);
    if (minRating) list = list.filter(p => p.rating >= minRating);
    if (sort === 'price_asc') list.sort((a, b) => a.price - b.price);
    else if (sort === 'price_desc') list.sort((a, b) => b.price - a.price);
    else if (sort === 'rating') list.sort((a, b) => b.rating - a.rating);
    return list;
  }, [searchQ, categoryQ, selectedBrands, priceRange, minRating, sort]);

  const toggleBrand = (brand) => setSelectedBrands(prev =>
    prev.includes(brand) ? prev.filter(b => b !== brand) : [...prev, brand]
  );

  const setCategory = (cat) => {
    const p = new URLSearchParams(params);
    if (cat) p.set('category', cat); else p.delete('category');
    setParams(p);
  };

  return (
    <div className="products-page container">
      {/* SIDEBAR */}
      <aside className="sidebar">
        <div className="sidebar-section">
          <h3>Department</h3>
          <ul className="sidebar-list">
            <li className={!categoryQ ? 'active' : ''} onClick={() => setCategory('')}>All Categories</li>
            {CATEGORIES.map(c => (
              <li key={c.name} className={categoryQ === c.name ? 'active' : ''} onClick={() => setCategory(c.name)}>
                {c.icon} {c.name}
              </li>
            ))}
          </ul>
        </div>

        <div className="sidebar-section">
          <h3>Avg. Customer Review</h3>
          {[4, 3, 2].map(r => (
            <label key={r} className="sidebar-radio">
              <input type="radio" name="rating" checked={minRating === r} onChange={() => setMinRating(r === minRating ? 0 : r)} />
              <span className="stars">{'★'.repeat(r)}{'☆'.repeat(5 - r)}</span> & Up
            </label>
          ))}
        </div>

        <div className="sidebar-section">
          <h3>Price</h3>
          <div className="price-inputs">
            <input type="number" placeholder="Min" value={priceRange[0] || ''} onChange={e => setPriceRange([+e.target.value || 0, priceRange[1]])} />
            <span>–</span>
            <input type="number" placeholder="Max" value={priceRange[1] || ''} onChange={e => setPriceRange([priceRange[0], +e.target.value || 200000])} />
          </div>
        </div>

        <div className="sidebar-section">
          <h3>Brand</h3>
          <ul className="sidebar-list">
            {brands.map(b => (
              <li key={b}>
                <label className="sidebar-check">
                  <input type="checkbox" checked={selectedBrands.includes(b)} onChange={() => toggleBrand(b)} />
                  {b}
                </label>
              </li>
            ))}
          </ul>
        </div>
      </aside>

      {/* MAIN RESULTS */}
      <main className="products-main">
        <div className="products-topbar">
          <div className="results-info">
            {searchQ && <span>Results for "<b>{searchQ}</b>" – </span>}
            {categoryQ && <span>Category: <b>{categoryQ}</b> – </span>}
            <span>{filtered.length} results</span>
          </div>
          <div className="sort-bar">
            <span>Sort by:</span>
            <select value={sort} onChange={e => setSort(e.target.value)}>
              {SORT_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
            </select>
          </div>
        </div>

        {filtered.length === 0 ? (
          <div className="no-results">
            <svg width="80" height="80" viewBox="0 0 24 24" fill="none" stroke="#ccc" strokeWidth="1"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
            <h3>No results found</h3>
            <p>Try different keywords or clear filters</p>
          </div>
        ) : (
          <div className="products-grid-4">
            {filtered.map(p => <ProductCard key={p._id} product={p} />)}
          </div>
        )}
      </main>
    </div>
  );
};

export default Products;
